    11	void TE_SYNC_ISR te_sync_edge(TeSync *s, uint32_t now_us, int level) {
    12	  if (!level) return;
    13	  if (s->rises == 0) {
    14	    s->last_rise_us = now_us;
    15	    s->rises = 1;
    16	    return;
    17	  }
    18	  const uint32_t gap = now_us - s->last_rise_us;
    19	  if (gap < TE_SYNC_MIN_PERIOD_US) return; /* a glitch: keep the true edge */
    20	
    21	  const uint32_t period = s->period_us;
    22	  if (gap <= TE_SYNC_MAX_PERIOD_US) {
    23	    /* an eighth of the way to each new gap, so a slow drift is followed */
    24	    if (!period)
    25	      s->period_us = gap;
    26	    else if (gap >= period)
    27	      s->period_us = period + (gap - period) / 8;
    28	    else
    29	      s->period_us = period - (period - gap) / 8;
    30	    s->rises = 2;
    31	  } else if (period) {
    32	    /* Edges the interrupt missed leave a whole number of periods; anything
    33	     * else is a restart, and the period is learnt again. */
    34	    const uint32_t k = (gap + period / 2) / period;
    35	    const uint32_t off = gap > k * period ? gap - k * period : k * period - gap;
    36	    if (k < 2 || off > period / 16) {
    37	      s->period_us = 0;
    38	      s->rises = 1;
    39	    }
    40	  } else {
    41	    s->rises = 1;
    42	  }
    43	  s->last_rise_us = now_us;
    44	}
