    48	uint32_t te_sync_wait_us(const TeSync *s, uint32_t now_us) {
    49	  const uint32_t period = s->period_us;
    50	  if (!period) return 0;
    51	  uint32_t since = now_us - s->last_rise_us;
    52	  if ((int32_t)since < 0) since = 0; /* the edge landed just after now was read */
    53	  if (since > s->timeout_us) return 0;
    54	  const uint32_t into = since % period;
    55	  const uint32_t offset = s->offset_us % period;
    56	  return into <= offset ? offset - into : period - into + offset;
    57	}
