    10	/* Times a push to the panel's refresh. The AMOLED scans its memory top to
    11	 * bottom 60 times a second, and a full push takes about two refreshes, so a
    12	 * push that starts at a random moment shows two pictures at once, with a seam
    13	 * between them: a thin line that moved a few pixels can fall in the gap and
    14	 * vanish for a frame. The panel's TE line pulses once a refresh. Starting a
    15	 * push at the same point in every cycle puts the seam where it is chosen, and
    16	 * the right point keeps the write ahead of the scan so there is none.
    17	 *
    18	 * An interrupt feeds it the edges of TE with the microsecond they arrived; the
    19	 * main loop asks how long to wait. Times are 32-bit microseconds that may
    20	 * wrap. */
    21	typedef struct {
    22	  volatile uint32_t last_rise_us;
    23	  volatile uint32_t period_us; /* 0 until two rising edges one period apart */
    24	  volatile uint32_t rises;     /* rising edges accepted, saturating at 2 */
    25	  uint32_t offset_us;
    26	  uint32_t timeout_us;
    27	} TeSync;
